package com.sabz.companion;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;import java.time.LocalDate;import org.json.*;
public class ReminderReceiver extends BroadcastReceiver {
 static final String CHANNEL="sabz_reminders";
 static void createChannel(Context c){NotificationChannel ch=new NotificationChannel(CHANNEL,"یادآوری سیب سلامت / Green Apple",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Check-ins, movement and nightly habit reviews");c.getSystemService(NotificationManager.class).createNotificationChannel(ch);}
 static PendingIntent alarmIntent(Context c,boolean check,boolean move,boolean review,String date){Intent i=new Intent(c,ReminderReceiver.class).setAction("com.sabz.companion.REMIND").putExtra("check",check).putExtra("move",move).putExtra("review",review).putExtra("date",date);return PendingIntent.getBroadcast(c,1,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void schedule(Context c){AlarmManager am=c.getSystemService(AlarmManager.class);am.cancel(alarmIntent(c,false,false,false,""));android.content.SharedPreferences p=c.getSharedPreferences("prefs",Context.MODE_PRIVATE);if(!p.getBoolean("enabled",false))return;ReminderSchedule.Next next=ReminderSchedule.next(System.currentTimeMillis(),java.time.ZoneId.systemDefault(),p.getInt("wake",8),p.getInt("sleep",22));if(next==null)return;PendingIntent pi=alarmIntent(c,next.check,next.move,next.review,next.date);try{if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.millis,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.millis,pi);}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next.millis,pi);}}

 private static void post(Context c,String title,String body,String date){createChannel(c);Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);if(date==null)open.putExtra("quick",true);else open.putExtra("reviewDate",date);PendingIntent content=PendingIntent.getActivity(c,date==null?2:3,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(R.drawable.ic_notification).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(content).setAutoCancel(true).build();try{c.getSystemService(NotificationManager.class).notify(date==null?7:8,n);}catch(SecurityException ignored){}}
 public static void notifyUser(Context c,boolean check,boolean move){boolean fa=c.getSharedPreferences("prefs",Context.MODE_PRIVATE).getBoolean("fa",true);String title=fa?"یک قدم کوچک برای حال بهتر 🍏":"A small step for a better day 🍏";String body=(check?(fa?"غذا، نوشیدنی، نشستن و فعالیتت را ثبت کن.":"Log food, drinks, sitting and activity."):"")+(move?(fa?" بلند شو، کمی حرکت کن و یک لیوان آب بنوش.":" Stand up, move a little and have a glass of water."):"");post(c,title,body,null);}
 static boolean recorded(JSONObject e,String key){return e.has(key)&&!e.isNull(key);}
 static NightReview.Data readDay(String raw,String date){NightReview.Data d=new NightReview.Data();try{JSONObject root=new JSONObject(raw),days=root.optJSONObject("days"),day=days==null?null:days.optJSONObject(date);if(day==null)return d;d.complete=day.optBoolean("complete",false);JSONObject g=day.optJSONObject("targets");if(g==null)return d;d.calorieGoal=g.getDouble("kcal");d.proteinGoal=g.getDouble("protein");d.fiberGoal=g.getDouble("fiber");d.waterGoal=g.getDouble("water");d.activityGoal=g.getDouble("activity");d.sittingLimit=g.getDouble("breakLimit");boolean food=false,drink=false,sitting=false,activity=false;JSONArray entries=day.getJSONArray("entries");for(int j=0;j<entries.length();j++){JSONObject e=entries.getJSONObject(j);food|=e.optBoolean("noFood",false);drink|=e.optBoolean("noDrink",false);sitting|=recorded(e,"sitting");activity|=recorded(e,"activity");double sit=e.optDouble("sitting",0);if(Double.isNaN(sit))sit=0;d.sitting+=sit;d.longest=Math.max(d.longest,sit);double active=e.optDouble("activity",0);if(!Double.isNaN(active))d.activity+=active;JSONArray items=e.getJSONArray("items");for(int k=0;k<items.length();k++){JSONObject i=items.getJSONObject(k),f=i.getJSONObject("food");double amount=i.getDouble("amount");boolean liquid=f.optBoolean("drink",false);drink|=liquid;food|=!liquid;if(f.optBoolean("water",false))d.water+=amount;for(String key:new String[]{"kcal","protein","fiber"}){if(!f.has(key)||f.isNull(key)){d.unknown=true;continue;}double value=f.getDouble(key)*amount/100;if(key.equals("kcal"))d.calories+=value;else if(key.equals("protein"))d.protein+=value;else d.fiber+=value;}}}d.coverage=food&&drink&&sitting&&activity;}catch(Exception error){d.complete=false;d.coverage=false;}return d;}
 public static void notifyReview(Context c,String date,boolean preview){if(date==null||!date.matches("\\d{4}-\\d{2}-\\d{2}"))date=LocalDate.now().toString();android.content.SharedPreferences p=c.getSharedPreferences("prefs",Context.MODE_PRIVATE);if(!preview&&date.equals(p.getString("lastReviewDate","")))return;boolean fa=p.getBoolean("fa",true);NightReview.Data d=readDay(c.getSharedPreferences("data",Context.MODE_PRIVATE).getString("state",""),date);String title=(fa?"جمع‌بندی روز 🍏":"Your daily review 🍏")+(date.equals(LocalDate.now().toString())?"":" · "+date);post(c,title,NightReview.message(d,fa),date);if(!preview)p.edit().putString("lastReviewDate",date).apply();}
 @Override public void onReceive(Context c,Intent i){if("com.sabz.companion.REMIND".equals(i.getAction())&&c.getSharedPreferences("prefs",Context.MODE_PRIVATE).getBoolean("enabled",false)){if(i.getBooleanExtra("review",false))notifyReview(c,i.getStringExtra("date"),false);else notifyUser(c,i.getBooleanExtra("check",false),i.getBooleanExtra("move",false));}schedule(c);}
}
